static __inline float projectile_render_clamp(float value)
{
    if (value > 1.0f) {
        return 1.0f;
    } else if (value < 0.0f) {
        return 0.0f;
    }
    return value;
}

static __inline float projectile_render_clamp(float value)
{
    return value > 1.0f
        ? 1.0f
        : (value < 0.0f ? 0.0f : value);
}
